"""Incremental Hoeffding tree learner for numeric data streams."""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Dict, List, Optional, Sequence, Tuple

from attribute_observers import NumericAttributeObserver
from classifiers import AbstractClassifier, compute_hoeffding_bound
from streams import Instance


@dataclass
class SplitSuggestion:
    """A candidate split gathered from a leaf's attribute observers."""

    attribute_index: int
    gain: float
    split_value: float
    post_split_distributions: List[List[float]]


class HoeffdingTreeNode:
    """Base node type used by the tree."""

    def __init__(self, depth: int):
        self.depth = depth

    def is_leaf(self) -> bool:
        raise NotImplementedError


class HoeffdingTreeLeaf(HoeffdingTreeNode):
    """Leaf node storing class counts and numeric split statistics."""

    def __init__(
        self,
        depth: int,
        num_attributes: int,
        num_classes: int,
        initial_class_counts: Optional[Sequence[float]] = None,
    ):
        super().__init__(depth)
        self.num_attributes = num_attributes
        self.num_classes = num_classes
        self.class_counts = [0.0] * num_classes
        if initial_class_counts is not None:
            for index, count in enumerate(initial_class_counts[:num_classes]):
                self.class_counts[index] = float(count)
        self.observers = [NumericAttributeObserver() for _ in range(num_attributes)]
        self.examples_seen = 0
        self.last_split_attempt_at = 0

    def is_leaf(self) -> bool:
        return True

    def ensure_num_classes(self, num_classes: int):
        if num_classes <= self.num_classes:
            return
        self.class_counts.extend([0.0] * (num_classes - self.num_classes))
        self.num_classes = num_classes

    def update(self, instance: Instance, weight: float = 1.0):
        self.ensure_num_classes(instance.label + 1)
        self.class_counts[instance.label] += weight
        for attr_index, value in enumerate(instance.features):
            self.observers[attr_index].observe(value, instance.label, weight)
        self.examples_seen += int(weight)

    def get_majority_class(self) -> int:
        if not self.class_counts:
            return 0
        best_index = 0
        best_count = self.class_counts[0]
        for index, count in enumerate(self.class_counts[1:], start=1):
            if count > best_count:
                best_count = count
                best_index = index
        return best_index

    def get_votes(self) -> Dict[int, float]:
        total = sum(self.class_counts)
        if total <= 0.0:
            return {}
        return {
            class_index: count / total
            for class_index, count in enumerate(self.class_counts)
            if count > 0.0
        }

    def get_split_suggestions(self, num_classes: int) -> List[SplitSuggestion]:
        suggestions: List[SplitSuggestion] = []
        for attr_index, observer in enumerate(self.observers):
            gain, split_value, post_dists = observer.get_best_split_suggestion(num_classes)
            suggestions.append(
                SplitSuggestion(
                    attribute_index=attr_index,
                    gain=gain,
                    split_value=split_value,
                    post_split_distributions=post_dists,
                )
            )
        suggestions.sort(key=lambda suggestion: suggestion.gain, reverse=True)
        return suggestions


class HoeffdingTreeSplit(HoeffdingTreeNode):
    """Binary split node for numeric threshold tests."""

    def __init__(
        self,
        depth: int,
        split_attribute: int,
        split_value: float,
        left_child: HoeffdingTreeNode,
        right_child: HoeffdingTreeNode,
    ):
        super().__init__(depth)
        self.split_attribute = split_attribute
        self.split_value = split_value
        self.children = [left_child, right_child]

    def is_leaf(self) -> bool:
        return False

    def branch_for_instance(self, instance: Instance) -> int:
        return 0 if instance.features[self.split_attribute] < self.split_value else 1

    def next_child(self, instance: Instance) -> HoeffdingTreeNode:
        return self.children[self.branch_for_instance(instance)]

    def set_child(self, branch: int, child: HoeffdingTreeNode):
        self.children[branch] = child


class HoeffdingTree(AbstractClassifier):
    """Very Fast Decision Tree (VFDT) for numeric attribute streams."""

    def __init__(
        self,
        grace_period: int = 200,
        split_confidence: float = 1e-7,
        tie_threshold: float = 0.05,
        max_depth: int = 20,
        num_classes: Optional[int] = None,
        num_attributes: Optional[int] = None,
    ):
        super().__init__()
        self.grace_period = grace_period
        self.split_confidence = split_confidence
        self.tie_threshold = tie_threshold
        self.max_depth = max_depth
        self.num_classes = num_classes
        self.num_attributes = num_attributes
        self.class_distribution: List[float] = [0.0] * num_classes if num_classes else []
        self.root: Optional[HoeffdingTreeNode] = None

    def _make_leaf(
        self,
        depth: int,
        initial_class_counts: Optional[Sequence[float]] = None,
    ) -> HoeffdingTreeLeaf:
        return HoeffdingTreeLeaf(
            depth=depth,
            num_attributes=self.num_attributes or 0,
            num_classes=self.num_classes or 2,
            initial_class_counts=initial_class_counts,
        )

    def _make_split(
        self,
        depth: int,
        split_attribute: int,
        split_value: float,
        left_child: HoeffdingTreeNode,
        right_child: HoeffdingTreeNode,
    ) -> HoeffdingTreeSplit:
        return HoeffdingTreeSplit(
            depth=depth,
            split_attribute=split_attribute,
            split_value=split_value,
            left_child=left_child,
            right_child=right_child,
        )

    def _ensure_structure(self, instance: Instance):
        if self.num_attributes is None:
            self.num_attributes = instance.num_attributes
        if self.num_classes is None:
            self.num_classes = max(2, instance.label + 1)
        elif instance.label >= self.num_classes:
            self.num_classes = instance.label + 1
        if len(self.class_distribution) < self.num_classes:
            self.class_distribution.extend([0.0] * (self.num_classes - len(self.class_distribution)))
            if self.root is not None:
                self._expand_leaf_classes(self.root, self.num_classes)
        if self.root is None:
            self.root = self._make_leaf(depth=0)

    def _expand_leaf_classes(self, node: HoeffdingTreeNode, num_classes: int):
        if node.is_leaf():
            leaf = node
            assert isinstance(leaf, HoeffdingTreeLeaf)
            leaf.ensure_num_classes(num_classes)
            return
        split = node
        assert isinstance(split, HoeffdingTreeSplit)
        for child in split.children:
            self._expand_leaf_classes(child, num_classes)

    def _majority_class(self, counts: Sequence[float]) -> int:
        if not counts:
            return 0
        best_class = 0
        best_count = counts[0]
        for class_index, count in enumerate(counts[1:], start=1):
            if count > best_count:
                best_count = count
                best_class = class_index
        return best_class

    def train(self, instance: Instance):
        self.instances_seen += 1
        self._ensure_structure(instance)
        self.class_distribution[instance.label] += 1.0
        assert self.root is not None
        self.root = self._train_node(self.root, instance)

    def _train_node(self, node: HoeffdingTreeNode, instance: Instance) -> HoeffdingTreeNode:
        if node.is_leaf():
            leaf = node
            assert isinstance(leaf, HoeffdingTreeLeaf)
            leaf.update(instance)
            if self._should_attempt_split(leaf):
                maybe_split = self._attempt_split(leaf)
                return maybe_split
            return leaf

        split = node
        assert isinstance(split, HoeffdingTreeSplit)
        branch = split.branch_for_instance(instance)
        split.set_child(branch, self._train_node(split.children[branch], instance))
        return split

    def _should_attempt_split(self, leaf: HoeffdingTreeLeaf) -> bool:
        if leaf.depth >= self.max_depth:
            return False
        return (leaf.examples_seen - leaf.last_split_attempt_at) >= self.grace_period

    def _attempt_split(self, leaf: HoeffdingTreeLeaf) -> HoeffdingTreeNode:
        leaf.last_split_attempt_at = leaf.examples_seen
        suggestions = leaf.get_split_suggestions(self.num_classes or 2)
        if not suggestions:
            return leaf

        best = suggestions[0]
        if best.gain <= 0.0 or not best.post_split_distributions:
            return leaf

        second_best_gain = suggestions[1].gain if len(suggestions) > 1 else 0.0
        range_val = math.log2(max(2, self.num_classes or 2))
        epsilon = compute_hoeffding_bound(range_val, self.split_confidence, leaf.examples_seen)
        if (best.gain - second_best_gain) <= epsilon and epsilon >= self.tie_threshold:
            return leaf

        left_child = self._make_leaf(leaf.depth + 1, best.post_split_distributions[0])
        right_child = self._make_leaf(leaf.depth + 1, best.post_split_distributions[1])
        return self._make_split(
            depth=leaf.depth,
            split_attribute=best.attribute_index,
            split_value=best.split_value,
            left_child=left_child,
            right_child=right_child,
        )

    def _traverse_to_leaf(self, instance: Instance) -> Optional[HoeffdingTreeLeaf]:
        node = self.root
        while node is not None and not node.is_leaf():
            split = node
            assert isinstance(split, HoeffdingTreeSplit)
            node = split.next_child(instance)
        if node is None:
            return None
        leaf = node
        assert isinstance(leaf, HoeffdingTreeLeaf)
        return leaf

    def predict(self, instance: Instance) -> int:
        leaf = self._traverse_to_leaf(instance)
        if leaf is not None and sum(leaf.class_counts) > 0.0:
            return leaf.get_majority_class()
        return self._majority_class(self.class_distribution)

    def get_votes(self, instance: Instance) -> Dict[int, float]:
        leaf = self._traverse_to_leaf(instance)
        if leaf is not None:
            votes = leaf.get_votes()
            if votes:
                return votes
        total = sum(self.class_distribution)
        if total <= 0.0:
            return {0: 1.0}
        return {
            class_index: count / total
            for class_index, count in enumerate(self.class_distribution)
            if count > 0.0
        }

    def get_tree_size(self) -> Dict[str, int]:
        num_leaves, num_splits = self._count_nodes(self.root)
        return {
            "num_leaves": num_leaves,
            "num_splits": num_splits,
            "total_nodes": num_leaves + num_splits,
        }

    def _count_nodes(self, node: Optional[HoeffdingTreeNode]) -> Tuple[int, int]:
        if node is None:
            return (0, 0)
        if node.is_leaf():
            return (1, 0)
        split = node
        assert isinstance(split, HoeffdingTreeSplit)
        left_counts = self._count_nodes(split.children[0])
        right_counts = self._count_nodes(split.children[1])
        return (
            left_counts[0] + right_counts[0],
            1 + left_counts[1] + right_counts[1],
        )

