"""Concept-adapting Hoeffding tree for drifting numeric streams."""

from __future__ import annotations

import math
from collections import deque
from dataclasses import dataclass, field
from typing import Deque, List, Optional, Sequence

from attribute_observers import NumericAttributeObserver
from classifiers import compute_hoeffding_bound
from hoeffding_tree import (
    HoeffdingTree,
    HoeffdingTreeLeaf,
    HoeffdingTreeNode,
    HoeffdingTreeSplit,
    SplitSuggestion,
)
from streams import Instance


def _fixed_range_observers(num_attributes: int) -> List[NumericAttributeObserver]:
    return [
        NumericAttributeObserver(num_bins=10, fixed_min=0.0, fixed_max=1.0)
        for _ in range(num_attributes)
    ]


class CVFDTLeaf(HoeffdingTreeLeaf):
    """Leaf node with reversible statistics for a sliding window."""

    def __init__(
        self,
        depth: int,
        num_attributes: int,
        num_classes: int,
        initial_class_counts: Optional[Sequence[float]] = None,
    ):
        super().__init__(
            depth=depth,
            num_attributes=num_attributes,
            num_classes=num_classes,
            initial_class_counts=initial_class_counts,
        )
        self.observers = _fixed_range_observers(num_attributes)

    def forget(self, instance: Instance, weight: float = 1.0):
        if instance.label < len(self.class_counts):
            self.class_counts[instance.label] = max(0.0, self.class_counts[instance.label] - weight)
        for attr_index, value in enumerate(instance.features):
            self.observers[attr_index].unobserve(value, instance.label, weight)
        self.examples_seen = max(0, self.examples_seen - int(weight))
        self.last_split_attempt_at = min(self.last_split_attempt_at, self.examples_seen)


@dataclass
class AlternateTreeState:
    """Background subtree grown for a potentially outdated split."""

    root: HoeffdingTreeNode
    challenger_attribute: int
    performance: Deque[int]

    def accuracy(self) -> float:
        if not self.performance:
            return 0.0
        return sum(self.performance) / len(self.performance)


class CVFDTSplit(HoeffdingTreeSplit):
    """Split node that keeps window statistics and alternate subtrees."""

    def __init__(
        self,
        depth: int,
        split_attribute: int,
        split_value: float,
        left_child: HoeffdingTreeNode,
        right_child: HoeffdingTreeNode,
        num_attributes: int,
        num_classes: int,
        performance_window: int,
    ):
        super().__init__(depth, split_attribute, split_value, left_child, right_child)
        self.num_attributes = num_attributes
        self.num_classes = num_classes
        self.class_counts = [0.0] * num_classes
        self.observers = _fixed_range_observers(num_attributes)
        self.examples_seen = 0
        self.alternate_trees: List[AlternateTreeState] = []
        self.main_performance: Deque[int] = deque(maxlen=performance_window)

    def ensure_num_classes(self, num_classes: int):
        if num_classes <= self.num_classes:
            return
        self.class_counts.extend([0.0] * (num_classes - self.num_classes))
        self.num_classes = num_classes

    def update(self, instance: Instance, weight: float = 1.0):
        self.ensure_num_classes(instance.label + 1)
        self.class_counts[instance.label] += weight
        for attr_index, value in enumerate(instance.features):
            self.observers[attr_index].observe(value, instance.label, weight)
        self.examples_seen += int(weight)

    def forget(self, instance: Instance, weight: float = 1.0):
        if instance.label < len(self.class_counts):
            self.class_counts[instance.label] = max(0.0, self.class_counts[instance.label] - weight)
        for attr_index, value in enumerate(instance.features):
            self.observers[attr_index].unobserve(value, instance.label, weight)
        self.examples_seen = max(0, self.examples_seen - int(weight))

    def get_split_suggestions(self, num_classes: int) -> List[SplitSuggestion]:
        suggestions: List[SplitSuggestion] = []
        for attr_index, observer in enumerate(self.observers):
            gain, split_value, post_dists = observer.get_best_split_suggestion(num_classes)
            suggestions.append(
                SplitSuggestion(
                    attribute_index=attr_index,
                    gain=gain,
                    split_value=split_value,
                    post_split_distributions=post_dists,
                )
            )
        suggestions.sort(key=lambda suggestion: suggestion.gain, reverse=True)
        return suggestions

    def main_accuracy(self) -> float:
        if not self.main_performance:
            return 0.0
        return sum(self.main_performance) / len(self.main_performance)


@dataclass
class WindowEntry:
    """Tracks which nodes were updated for a windowed training instance."""

    instance: Instance
    main_path_nodes: List[HoeffdingTreeNode] = field(default_factory=list)
    stats_nodes: List[object] = field(default_factory=list)


class CVFDT(HoeffdingTree):
    """CVFDT with sliding-window forgetting and alternate subtree replacement."""

    def __init__(
        self,
        grace_period: int = 300,
        split_confidence: float = 0.0001,
        tie_threshold: float = 0.05,
        window_size: int = 10000,
        check_frequency: int = 2000,
        max_depth: int = 20,
        num_classes: Optional[int] = None,
        num_attributes: Optional[int] = None,
    ):
        super().__init__(
            grace_period=grace_period,
            split_confidence=split_confidence,
            tie_threshold=tie_threshold,
            max_depth=max_depth,
            num_classes=num_classes,
            num_attributes=num_attributes,
        )
        self.window_size = window_size
        self.check_frequency = check_frequency
        self.performance_window = max(grace_period, check_frequency)
        self.window: Deque[WindowEntry] = deque(maxlen=window_size)

    def _make_leaf(
        self,
        depth: int,
        initial_class_counts: Optional[Sequence[float]] = None,
    ) -> CVFDTLeaf:
        return CVFDTLeaf(
            depth=depth,
            num_attributes=self.num_attributes or 0,
            num_classes=self.num_classes or 2,
            initial_class_counts=initial_class_counts,
        )

    def _make_split(
        self,
        depth: int,
        split_attribute: int,
        split_value: float,
        left_child: HoeffdingTreeNode,
        right_child: HoeffdingTreeNode,
    ) -> CVFDTSplit:
        return CVFDTSplit(
            depth=depth,
            split_attribute=split_attribute,
            split_value=split_value,
            left_child=left_child,
            right_child=right_child,
            num_attributes=self.num_attributes or 0,
            num_classes=self.num_classes or 2,
            performance_window=self.performance_window,
        )

    def train(self, instance: Instance):
        self.instances_seen += 1
        self._ensure_structure(instance)
        if len(self.window) == self.window_size:
            evicted = self.window.popleft()
            self._forget_entry(evicted)
        self.class_distribution[instance.label] += 1.0

        entry = WindowEntry(instance=instance)
        assert self.root is not None
        self.root = self._train_main_tree(self.root, instance, entry.main_path_nodes, entry.stats_nodes)
        self._train_alternates(instance, entry.main_path_nodes, entry.stats_nodes)
        self.window.append(entry)

        if self.check_frequency > 0 and (self.instances_seen % self.check_frequency) == 0:
            assert self.root is not None
            self.root = self._check_split_validity(self.root)

    def _forget_entry(self, entry: WindowEntry):
        self.class_distribution[entry.instance.label] = max(
            0.0, self.class_distribution[entry.instance.label] - 1.0
        )
        for node in entry.stats_nodes:
            if hasattr(node, "forget"):
                node.forget(entry.instance)

    def _train_main_tree(
        self,
        node: HoeffdingTreeNode,
        instance: Instance,
        main_path_nodes: List[HoeffdingTreeNode],
        stats_nodes: List[object],
    ) -> HoeffdingTreeNode:
        main_path_nodes.append(node)
        stats_nodes.append(node)

        if node.is_leaf():
            leaf = node
            assert isinstance(leaf, CVFDTLeaf)
            leaf.update(instance)
            if self._should_attempt_split(leaf):
                return self._attempt_split(leaf)
            return leaf

        split = node
        assert isinstance(split, CVFDTSplit)
        split.main_performance.append(int(self._predict_from_node(split, instance) == instance.label))
        for alternate in split.alternate_trees:
            alternate.performance.append(int(self._predict_from_node(alternate.root, instance) == instance.label))
        split.update(instance)
        branch = split.branch_for_instance(instance)
        split.set_child(
            branch,
            self._train_main_tree(split.children[branch], instance, main_path_nodes, stats_nodes),
        )
        return split

    def _train_alternates(
        self,
        instance: Instance,
        main_path_nodes: Sequence[HoeffdingTreeNode],
        stats_nodes: List[object],
    ):
        for node in main_path_nodes:
            if not isinstance(node, CVFDTSplit):
                continue
            if not node.alternate_trees:
                continue
            for alternate in node.alternate_trees:
                alternate.root = self._train_subtree(alternate.root, instance, stats_nodes)

    def _train_subtree(
        self,
        node: HoeffdingTreeNode,
        instance: Instance,
        stats_nodes: List[object],
    ) -> HoeffdingTreeNode:
        stats_nodes.append(node)
        if node.is_leaf():
            leaf = node
            assert isinstance(leaf, CVFDTLeaf)
            leaf.update(instance)
            if self._should_attempt_split(leaf):
                return self._attempt_split(leaf)
            return leaf

        split = node
        assert isinstance(split, CVFDTSplit)
        split.update(instance)
        branch = split.branch_for_instance(instance)
        split.set_child(branch, self._train_subtree(split.children[branch], instance, stats_nodes))
        return split

    def _predict_from_node(self, node: HoeffdingTreeNode, instance: Instance) -> int:
        current = node
        while not current.is_leaf():
            split = current
            assert isinstance(split, HoeffdingTreeSplit)
            current = split.next_child(instance)
        leaf = current
        assert isinstance(leaf, HoeffdingTreeLeaf)
        if sum(leaf.class_counts) <= 0.0:
            return self._majority_class(self.class_distribution)
        return leaf.get_majority_class()

    def _check_split_validity(self, node: HoeffdingTreeNode) -> HoeffdingTreeNode:
        if node.is_leaf():
            return node

        split = node
        assert isinstance(split, CVFDTSplit)
        split.children[0] = self._check_split_validity(split.children[0])
        split.children[1] = self._check_split_validity(split.children[1])

        if split.examples_seen < self.grace_period:
            return split

        suggestions = split.get_split_suggestions(self.num_classes or 2)
        if not suggestions:
            return split

        best = suggestions[0]
        current_gain = 0.0
        for suggestion in suggestions:
            if suggestion.attribute_index == split.split_attribute:
                current_gain = suggestion.gain
                break

        epsilon = compute_hoeffding_bound(
            math.log2(max(2, self.num_classes or 2)),
            self.split_confidence,
            max(1, split.examples_seen),
        )
        should_challenge = (
            best.attribute_index != split.split_attribute
            and best.gain > 0.0
            and ((best.gain - current_gain) > epsilon or epsilon < self.tie_threshold)
        )
        if should_challenge:
            if not split.alternate_trees or split.alternate_trees[0].challenger_attribute != best.attribute_index:
                split.alternate_trees = [self._start_alternate(split, best.attribute_index)]

        if not split.alternate_trees:
            return split

        next_alternates: List[AlternateTreeState] = []
        for alternate in split.alternate_trees:
            observations = len(alternate.performance)
            if observations >= max(self.grace_period, self.check_frequency // 2):
                alt_accuracy = alternate.accuracy()
                main_accuracy = split.main_accuracy()
                if alt_accuracy > (main_accuracy + 0.01):
                    return alternate.root
                if observations >= self.check_frequency and main_accuracy > (alt_accuracy + 0.05):
                    continue
            next_alternates.append(alternate)
        split.alternate_trees = next_alternates
        return split

    def _start_alternate(self, host_split: CVFDTSplit, challenger_attribute: int) -> AlternateTreeState:
        performance: Deque[int] = deque(maxlen=self.performance_window)
        state = AlternateTreeState(
            root=self._make_leaf(host_split.depth),
            challenger_attribute=challenger_attribute,
            performance=performance,
        )
        for entry in self.window:
            if host_split not in entry.main_path_nodes:
                continue
            state.root = self._train_subtree(state.root, entry.instance, entry.stats_nodes)
            state.performance.append(int(self._predict_from_node(state.root, entry.instance) == entry.instance.label))
        return state

