"""ADWIN drift detector with exponential histogram compression."""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Iterator, List, Optional, Tuple


@dataclass
class Bucket:
    """Summary statistics for a bucket in the ADWIN histogram."""

    total: float
    variance_sum: float
    count: int
    prev: Optional["Bucket"] = None
    next: Optional["Bucket"] = None

    def merge(self, other: "Bucket") -> "Bucket":
        if self.count == 0:
            return Bucket(other.total, other.variance_sum, other.count)
        if other.count == 0:
            return Bucket(self.total, self.variance_sum, self.count)
        merged_count = self.count + other.count
        merged_total = self.total + other.total
        mean_self = self.total / self.count
        mean_other = other.total / other.count
        delta = mean_other - mean_self
        merged_variance = (
            self.variance_sum
            + other.variance_sum
            + (delta * delta * self.count * other.count / merged_count)
        )
        return Bucket(merged_total, merged_variance, merged_count)


class BucketRow:
    """Doubly-linked list of buckets at the same granularity level."""

    def __init__(self):
        self.size = 0
        self.head: Optional[Bucket] = None
        self.tail: Optional[Bucket] = None

    def add_to_tail(self, bucket: Bucket):
        bucket.prev = self.tail
        bucket.next = None
        if self.tail is None:
            self.head = bucket
        else:
            self.tail.next = bucket
        self.tail = bucket
        self.size += 1

    def remove_from_head(self) -> Bucket:
        if self.head is None:
            raise IndexError("cannot remove from an empty BucketRow")
        bucket = self.head
        self.head = bucket.next
        if self.head is None:
            self.tail = None
        else:
            self.head.prev = None
        bucket.prev = None
        bucket.next = None
        self.size -= 1
        return bucket

    def iter_oldest_to_newest(self) -> Iterator[Bucket]:
        current = self.head
        while current is not None:
            yield current
            current = current.next


def _summary_from_bucket(bucket: Bucket) -> Tuple[int, float, float]:
    return (bucket.count, bucket.total, bucket.variance_sum)


def _merge_summaries(
    left: Tuple[int, float, float],
    right: Tuple[int, float, float],
) -> Tuple[int, float, float]:
    left_count, left_total, left_variance = left
    right_count, right_total, right_variance = right
    if left_count == 0:
        return right
    if right_count == 0:
        return left
    merged_count = left_count + right_count
    merged_total = left_total + right_total
    mean_left = left_total / left_count
    mean_right = right_total / right_count
    delta = mean_right - mean_left
    merged_variance = (
        left_variance
        + right_variance
        + (delta * delta * left_count * right_count / merged_count)
    )
    return (merged_count, merged_total, merged_variance)


def _subtract_summaries(
    whole: Tuple[int, float, float],
    part: Tuple[int, float, float],
) -> Tuple[int, float, float]:
    whole_count, whole_total, whole_variance = whole
    part_count, part_total, part_variance = part
    remaining_count = whole_count - part_count
    if remaining_count <= 0:
        return (0, 0.0, 0.0)
    remaining_total = whole_total - part_total
    mean_part = part_total / part_count
    mean_remaining = remaining_total / remaining_count
    correction = ((mean_part - mean_remaining) ** 2) * part_count * remaining_count / whole_count
    remaining_variance = max(0.0, whole_variance - part_variance - correction)
    return (remaining_count, remaining_total, remaining_variance)


class ADWIN:
    """Adaptive windowing drift detector."""

    def __init__(
        self,
        delta: float = 0.002,
        max_buckets_per_row: int = 5,
        min_window_length: int = 10,
    ):
        self.delta = delta
        self.max_buckets_per_row = max_buckets_per_row
        self.min_window_length = min_window_length
        self.rows: List[BucketRow] = []
        self.width = 0
        self.total = 0.0
        self.variance = 0.0
        self._variance_sum = 0.0
        self._last_detected_change = False

    def add_element(self, value: float) -> bool:
        self._last_detected_change = False
        self._ensure_row(0)
        old_width = self.width
        old_mean = self.total / old_width if old_width > 0 else 0.0
        self.width += 1
        self.total += value
        new_mean = self.total / self.width
        if old_width > 0:
            self._variance_sum += (value - old_mean) * (value - new_mean)
        self.variance = self._variance_sum / self.width if self.width > 0 else 0.0

        self.rows[0].add_to_tail(Bucket(total=value, variance_sum=0.0, count=1))
        self._compress()
        self._last_detected_change = self._check_for_change()
        return self._last_detected_change

    def detected_change(self) -> bool:
        return self._last_detected_change

    def get_estimation(self) -> float:
        if self.width == 0:
            return 0.0
        return self.total / self.width

    def reset(self):
        self.rows = []
        self.width = 0
        self.total = 0.0
        self.variance = 0.0
        self._variance_sum = 0.0
        self._last_detected_change = False

    def _ensure_row(self, index: int):
        while len(self.rows) <= index:
            self.rows.append(BucketRow())

    def _compress(self):
        row_index = 0
        while row_index < len(self.rows):
            row = self.rows[row_index]
            while row.size > self.max_buckets_per_row:
                first = row.remove_from_head()
                second = row.remove_from_head()
                merged = first.merge(second)
                self._ensure_row(row_index + 1)
                self.rows[row_index + 1].add_to_tail(merged)
            row_index += 1

    def _check_for_change(self) -> bool:
        if self.width < (2 * self.min_window_length):
            return False

        change_detected = False
        while self.width >= (2 * self.min_window_length):
            left_summary = (0, 0.0, 0.0)
            whole_summary = (self.width, self.total, self._variance_sum)
            cut_found = False
            for bucket in self._iter_buckets_oldest_to_newest():
                left_summary = _merge_summaries(left_summary, _summary_from_bucket(bucket))
                right_summary = _subtract_summaries(whole_summary, left_summary)
                left_count, left_total, _ = left_summary
                right_count, right_total, _ = right_summary
                if left_count < self.min_window_length or right_count < self.min_window_length:
                    continue
                left_mean = left_total / left_count
                right_mean = right_total / right_count
                if abs(left_mean - right_mean) > self._compute_epsilon(left_count, right_count):
                    self._drop_oldest_prefix(left_count)
                    change_detected = True
                    cut_found = True
                    break
            if not cut_found:
                break
        self._last_detected_change = change_detected
        return change_detected

    def _compute_epsilon(self, left_count: int, right_count: int) -> float:
        if self.width <= 1:
            return float("inf")
        window_variance = self._variance_sum / self.width if self.width > 0 else 0.0
        dd = math.log((2.0 * math.log(max(2.0, float(self.width)))) / self.delta)
        harmonic = (
            1.0 / (left_count - self.min_window_length + 1)
            + 1.0 / (right_count - self.min_window_length + 1)
        )
        return math.sqrt(2.0 * harmonic * window_variance * dd) + ((2.0 / 3.0) * dd * harmonic)

    def _drop_oldest_prefix(self, count_to_remove: int):
        remaining = count_to_remove
        while remaining > 0:
            row_index = self._oldest_non_empty_row_index()
            if row_index is None:
                break
            bucket = self.rows[row_index].remove_from_head()
            self._remove_bucket_from_window(bucket)
            remaining -= bucket.count
        while self.rows and self.rows[-1].size == 0:
            self.rows.pop()

    def _remove_bucket_from_window(self, bucket: Bucket):
        whole_summary = (self.width, self.total, self._variance_sum)
        reduced = _subtract_summaries(whole_summary, _summary_from_bucket(bucket))
        self.width, self.total, self._variance_sum = reduced
        self.variance = self._variance_sum / self.width if self.width > 0 else 0.0

    def _oldest_non_empty_row_index(self) -> Optional[int]:
        for row_index in range(len(self.rows) - 1, -1, -1):
            if self.rows[row_index].size > 0:
                return row_index
        return None

    def _iter_buckets_oldest_to_newest(self) -> Iterator[Bucket]:
        for row_index in range(len(self.rows) - 1, -1, -1):
            row = self.rows[row_index]
            yield from row.iter_oldest_to_newest()

