"""Synthetic experiments for ADWIN drift detection."""

from __future__ import annotations

import random
from typing import Dict, Iterable, List, Optional

from stream.adwin import ADWIN


class ADWINExperiment:
    """Benchmark suite for the ADWIN detector."""

    def __init__(self, delta: float = 0.002):
        self.delta = delta

    def _stationary_stream(
        self,
        seed: int,
        length: int,
        mean: float = 0.0,
        stddev: float = 1.0,
    ) -> Iterable[float]:
        rng = random.Random(seed)
        for _ in range(length):
            yield rng.gauss(mean, stddev)

    def _abrupt_stream(
        self,
        seed: int,
        length: int,
        change_point: int,
        before_mean: float,
        after_mean: float,
        stddev: float = 1.0,
    ) -> Iterable[float]:
        rng = random.Random(seed)
        for index in range(length):
            mean = before_mean if index < change_point else after_mean
            yield rng.gauss(mean, stddev)

    def _gradual_stream(
        self,
        seed: int,
        length: int,
        start: int,
        end: int,
        before_mean: float,
        after_mean: float,
        stddev: float = 1.0,
    ) -> Iterable[float]:
        rng = random.Random(seed)
        for index in range(length):
            if index < start:
                mean = before_mean
            elif index >= end:
                mean = after_mean
            else:
                ratio = (index - start) / max(1, end - start)
                mean = before_mean + ((after_mean - before_mean) * ratio)
            yield rng.gauss(mean, stddev)

    def _recurring_stream(
        self,
        seed: int,
        segments: List[tuple[int, int, float]],
        stddev: float = 1.0,
    ) -> Iterable[float]:
        rng = random.Random(seed)
        for start, end, mean in segments:
            for _ in range(max(0, end - start)):
                yield rng.gauss(mean, stddev)

    def _first_detection_index(
        self,
        stream: Iterable[float],
        min_index: int = 0,
    ) -> Optional[tuple[int, int]]:
        detector = ADWIN(delta=self.delta)
        for index, value in enumerate(stream):
            if detector.add_element(value) and index >= min_index:
                return (index, detector.width)
        return None

    def detection_delay(self) -> float:
        delays = []
        for seed in range(1, 6):
            result = self._first_detection_index(
                self._abrupt_stream(seed, 10000, 5000, 0.0, 1.0),
                min_index=5000,
            )
            if result is None:
                delays.append(5000.0)
            else:
                delays.append(float(result[0] - 5000))
        return sum(delays) / len(delays)

    def false_positive_rate(self) -> float:
        detector = ADWIN(delta=self.delta)
        detections = 0
        for value in self._stationary_stream(seed=42, length=10000):
            if detector.add_element(value):
                detections += 1
        return detections / 10000.0

    def average_window_size_stable(self) -> float:
        detector = ADWIN(delta=self.delta)
        total_width = 0.0
        for value in self._stationary_stream(seed=42, length=5000):
            detector.add_element(value)
            total_width += detector.width
        return total_width / 5000.0

    def window_size_after_drift(self) -> float:
        widths = []
        for seed in range(1, 6):
            result = self._first_detection_index(
                self._abrupt_stream(seed, 10000, 5000, 0.0, 1.0),
                min_index=5000,
            )
            widths.append(float(result[1]) if result is not None else 0.0)
        return sum(widths) / len(widths)

    def mean_estimation_error(self) -> float:
        detector = ADWIN(delta=self.delta)
        current_estimate = 0.0
        for index, value in enumerate(self._abrupt_stream(42, 10000, 5000, 0.0, 2.0)):
            detector.add_element(value)
            if index == 7000:
                current_estimate = detector.get_estimation()
                break
        return abs(current_estimate - 2.0)

    def run(self) -> Dict[str, float]:
        return {
            "ADWIN_DETECTION_DELAY": self.detection_delay(),
            "ADWIN_FALSE_POSITIVE_RATE": self.false_positive_rate(),
            "ADWIN_WINDOW_SIZE_STABLE": self.average_window_size_stable(),
            "ADWIN_WINDOW_SIZE_DRIFT": self.window_size_after_drift(),
            "ADWIN_MEAN_ESTIMATION_ERROR": self.mean_estimation_error(),
        }
